// --- INFORMACOES DA RACA ---
std::string Fairy::getRaceName() const 
{ 
    return "Fada"; 
}

Attributes Fairy::getAttributesRace() const 
{ 
    return { 40, 0, 20, 2, 5, 5, 5 }; 
}

std::vector<std::unique_ptr<Item>> Fairy::getEquipmentRace() const 
{
    std::vector<std::unique_ptr<Item>> equipment;
    equipment.push_back(ItemFactory::createItem(ItemID::WandCorroded));
    return equipment;
}

// --- HABILIDADE DA RACA ---
std::string Fairy::getNameSkillRace() const { return "Nenhuma"; }
std::string Fairy::getDescriptionSkillRace() const { return "Monstros nao possuem passivas"; }

